import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

// Rebuilds src/yoga/vendor from the installed yoga-layout with its wasm lowered
// to WebAssembly MVP, so Yoga instantiates on Chrome 57-73 (sign-ext needs 74).
// Run `pnpm vendor:yoga` after bumping yoga-layout; yogaVendor.spec.ts fails
// until you do.

const BINARYEN = 'binaryen@132.0.0';
const DATA_URI_PREFIX = 'data:application/octet-stream;base64,';
const SCRIPT_DIR_LINE = 'var _scriptDir = import.meta.url;';

const pkgDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const outDir = path.join(pkgDir, 'src/yoga/vendor');
const yogaDist = path.resolve(fileURLToPath(import.meta.resolve('yoga-layout/load')), '../..');
const yogaPkgJson = path.join(yogaDist, '../package.json');
const yogaVersion: string = JSON.parse(readFileSync(yogaPkgJson, 'utf8')).version;

const readUpstream = (file: string) =>
  readFileSync(path.join(yogaDist, file), 'utf8').replace(/\n\/\/# sourceMappingURL=.*$/m, '\n');

const wasmOpt = (args: string[]) =>
  execFileSync('pnpm', ['--silent', `--package=${BINARYEN}`, 'dlx', 'wasm-opt', ...args], {
    stdio: ['ignore', 'inherit', 'inherit'],
    env: { ...process.env, NODE_NO_WARNINGS: '1' },
  });

const glue = readUpstream('binaries/yoga-wasm-base64-esm.js');
const match = glue.match(/data:application\/octet-stream;base64,([A-Za-z0-9+/=]+)/);

if (!match?.[1]) {
  throw new Error('No embedded wasm found in yoga-wasm-base64-esm.js');
}

if (!glue.includes(SCRIPT_DIR_LINE)) {
  throw new Error(`Expected "${SCRIPT_DIR_LINE}" in the yoga glue, check the upstream build`);
}

const original = Buffer.from(match[1], 'base64');
const tmp = mkdtempSync(path.join(tmpdir(), 'yoga-mvp-'));

try {
  const inFile = path.join(tmp, 'yoga.wasm');
  const outFile = path.join(tmp, 'yoga-mvp.wasm');

  writeFileSync(inFile, original);
  wasmOpt([inFile, '--enable-sign-ext', '--signext-lowering', '-o', outFile]);
  // Fails (non-zero exit) if anything beyond MVP is left.
  wasmOpt([outFile, '--mvp-features', '--quiet', '-o', path.join(tmp, 'validated.wasm')]);

  const lowered = readFileSync(outFile);
  const sha = createHash('sha256').update(original).digest('hex');
  const header = [
    `// Generated by scripts/vendorYoga.ts from yoga-layout@${yogaVersion} (MIT, Meta Platforms, Inc.). Do not edit.`,
    `// The wasm is lowered to WebAssembly MVP with ${BINARYEN} (--signext-lowering).`,
    `// source-wasm-sha256: ${sha}`,
    '',
  ].join('\n');

  // import.meta is a syntax error before Chrome 64, and the wasm is a data URI so
  // the script dir is never used.
  const vendoredGlue = glue
    .replace(match[0], DATA_URI_PREFIX + lowered.toString('base64'))
    .replace(SCRIPT_DIR_LINE, 'var _scriptDir = "";');

  writeFileSync(path.join(outDir, 'yoga-wasm-mvp.js'), header + vendoredGlue);
  writeFileSync(
    path.join(outDir, 'wrapAssembly.js'),
    readUpstream('src/wrapAssembly.js').replaceAll('./generated/YGEnums.js', './YGEnums.js'),
  );
  writeFileSync(path.join(outDir, 'YGEnums.js'), readUpstream('src/generated/YGEnums.js'));

  console.log(
    `Vendored yoga-layout@${yogaVersion}: ${original.length} -> ${lowered.length} bytes of wasm`,
  );
} finally {
  rmSync(tmp, { recursive: true, force: true });
}
